  : `✅ [n8n Report] All Systems Healthy (${activeWorkflows.length} Active Workflows)`;

return [{
  json: {
    isUrgent,
    failedCount,
    successCount,
    totalRecordedExecutions,
    activeWorkflowsCount: activeWorkflows.length,
